it('should honor shouldDirty when the form is disabled', async () => {
  let getFieldState: ReturnType<typeof useForm>['getFieldState'];
  let setValue: ReturnType<typeof useForm>['setValue'];

  const App = () => {
    const methods = useForm({
      disabled: true,
      defaultValues: { name: 'default' },
    });
    const { isDirty, dirtyFields } = methods.formState;

    ({ getFieldState, setValue } = methods);

    return (
      <>
        <input {...methods.register('name')} />
        <p>{isDirty.toString()}</p>
        <p>{JSON.stringify(dirtyFields)}</p>
      </>
    );
  };

  render(<App />);

  act(() => setValue('name', 'changed', { shouldDirty: true }));

  await waitFor(() => {
    expect(getFieldState('name').isDirty).toBe(true);
    expect(screen.getByText('true')).toBeVisible();
    expect(screen.getByText(JSON.stringify({ name: true }))).toBeVisible();
  });

  act(() => setValue('name', 'default', { shouldDirty: true }));

  await waitFor(() => {
    expect(getFieldState('name').isDirty).toBe(false);
    expect(screen.getByText('false')).toBeVisible();
    expect(screen.getByText('{}')).toBeVisible();
  });
});

